def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    value = new - old

    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "dollars"
            }
        }
    }
